window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Ct9hIkPmbYg","speaker":"Alexander Stubb","role":"President","country":"Finland","region":"Europe","url":"https://www.youtube.com/watch?v=Ct9hIkPmbYg","date":"20260922","title":"🇫🇮 Finland - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1164,"words":2529,"counts":{"claims":32,"promises":4,"attacks":0},"topics":[{"topic":"UN reform","share":0.2194,"seconds":255},{"topic":"International law","share":0.1135,"seconds":132},{"topic":"Ukraine","share":0.1082,"seconds":126},{"topic":"armed conflicts","share":0.0615,"seconds":72},{"topic":"Helsinki Final Act","share":0.0591,"seconds":69},{"topic":"Global interdependence","share":0.0573,"seconds":67},{"topic":"multilateralism","share":0.0559,"seconds":65},{"topic":"AI governance","share":0.0559,"seconds":65},{"topic":"Gaza","share":0.0557,"seconds":65},{"topic":"Global economy","share":0.0549,"seconds":64},{"topic":"Ceremony","share":0.0542,"seconds":63},{"topic":"Sudan","share":0.0529,"seconds":62},{"topic":"UN cooperation","share":0.0516,"seconds":60}],"timeline":[[1,64,"Ceremony"],[65,125,"UN cooperation"],[126,198,"armed conflicts"],[199,264,"multilateralism"],[265,327,"Ukraine"],[327,391,"Ukraine"],[392,461,"Helsinki Final Act"],[463,530,"Global interdependence"],[531,595,"Global economy"],[596,662,"International law"],[663,730,"International law"],[731,792,"Sudan"],[794,858,"Gaza"],[859,920,"UN reform"],[921,982,"UN reform"],[983,1048,"UN reform"],[1049,1114,"AI governance"],[1116,1185,"UN reform"]],"stances":{"Ceremony":"Alexander Stubb pays tribute to Ambassador Elena Kalo for her 44-year career and upcoming retirement while introducing himself as the President of Finland.","UN cooperation":"Alexander Stubb argues that global disorder results from forgetting the principle of standing together and highlights a current choice between conflict and cooperation due to eroding trust and institutions.","armed conflicts":"Alexander Stubb states that while competition is natural, the increasing disregard for international rules is concerning and requires a defense of multilateralism.","multilateralism":"Alexander Stubb argues that while multilateralism is difficult, it remains the best option for humanity and that a shift toward a non-cooperative multipolar order will lead to conflict.","Ukraine":"Alexander Stubb supports the coalition of the willing for Ukraine as a force of good that builds on multilateralism to end Russia's unlawful war.","Helsinki Final Act":"Alexander Stubb cites the Helsinki Final Act as a historical example of reducing tensions and building common ground despite deep disagreements, suggesting similar principles could apply to regions like the Middle East.","Global interdependence":"Alexander Stubb argues that the world has shifted from a belief in interdependence bringing peace to a reality of coercion and weaponized dependencies, requiring a new geopolitical order based on realistic power balances.","Global economy":"Alexander Stubb argues that the world has slipped into disorder due to nations competing at the expense of rules and calls for a return to international law, institutions, and agreements to restore stability.","International law":"Alexander Stubb argues that the erosion of international rules and values is creating a critical juncture where raw power prevails, necessitating a return to the rule of law as the primary remedy.","Sudan":"Alexander Stubb states that Sudan is devastated by war, resulting in mass displacement and famine.","Gaza":"Alexander Stubb describes the situation in Gaza as an acute humanitarian emergency and argues against indifference to such suffering.","UN reform":"Alexander Stubb emphasizes the need to continue work on reforming and rationalizing the UN system while thanking the Secretary General for his service.","AI governance":"Alexander Stubb advocates for international cooperation to develop control mechanisms for frontier AI models and calls for UN member states to join this initiative."},"claims":[{"t":39,"quote":"She is the Finnish UN representative and she has had an absolutely wonderful 44year career uh in the Finnish diplomatic service and she will retire in the month of October.","topic":"Ceremony","kind":"fact"},{"t":71,"quote":"Whatever our differences, we stand or fall together.","topic":"UN cooperation","kind":"fact"},{"t":84,"quote":"Last year, from this very podium, I stated that foreign policy is based on three pillars: values, interests, and power.","topic":"UN cooperation","kind":"self_credit"},{"t":126,"quote":"According to some accounts, there are currently 65 active armed conflicts, more than at any time since the end of the Cold War.","topic":"armed conflicts","kind":"number"},{"t":215,"quote":"Strobe Talbbert reportedly remarked, multilateralism is hell and can be a real pain in the neck, but it is the best option for humanity as a whole.","topic":"multilateralism","kind":"fact"},{"t":228,"quote":"We need multilateralism in order to address our shared agenda, ranging from conflicts and climate change to sustainable development and artificial intelligence.","topic":"multilateralism","kind":"fact"},{"t":310,"quote":"The coalition of the willing for Ukraine is particularly close to my heart. It's a group of countries working to end Russia's war of aggression.","topic":"Ukraine","kind":"fact"},{"t":318,"quote":"The war is unlawful, unjustified, and unprovoked.","topic":"Ukraine","kind":"fact"},{"t":332,"quote":"The coalition works for a just and lasting peace in Ukraine in accordance with the UN charter.","topic":"Ukraine","kind":"fact"},{"t":368,"quote":"We're seeing an intensification of regional integration. akin to what we saw in the immediate aftermath of World War II.","topic":"Ukraine","kind":"fact"},{"t":392,"quote":"We Finns are happy to point out the historic signing of the Helsinki Final Act in 1975. It brought together 35 nations in the midst of the Cold War and laid the foundations for what would later become the Organization for Security and Cooperation in Europe.","topic":"Helsinki Final Act","kind":"fact"},{"t":450,"quote":"Instruments once used for economic integration such as trade, technology, energy, investment, and supply chains have become instruments of geopolitical competition.","topic":"Helsinki Final Act","kind":"fact"},{"t":463,"quote":"There was perhaps a time a naive at at times a naive belief that interdependence would bring about stability and peace.","topic":"Global interdependence","kind":"fact"},{"t":477,"quote":"We've entered a world of coercion where dependencies are Countries seek choke points that can be weaponized to pressure others.","topic":"Global interdependence","kind":"fact"},{"t":568,"quote":"too many nations now compete at the expense of basic rules. And that is why the world has slipped into disorder.","topic":"Global economy","kind":"fact"},{"t":603,"quote":"The breach of one rule inevitably leads to the breach of other rules.","topic":"International law","kind":"fact"},{"t":618,"quote":"We've moved back to a world defined by raw power and self-interest.","topic":"International law","kind":"fact"},{"t":663,"quote":"Today, international norms are often presented as an obstacle to the pursuit of national interest. This is both wrong and dangerous.","topic":"International law","kind":"fact"},{"t":687,"quote":"Despite the rhetoric, no major power is likely to give up its ability to shape the rules.","topic":"International law","kind":"fact"},{"t":760,"quote":"Since the establishment of the United Nations, poverty has declined, access to basic education has expanded, literacy literacy has increased, and child mortality has fallen.","topic":"Sudan","kind":"fact"},{"t":785,"quote":"For example, Sudan is devastated by war. Millions have been displaced and many face famine.","topic":"Sudan","kind":"fact"},{"t":795,"quote":"Gaza continues to be one of the world's most acute humanitarian emergencies marked by mass dis displacement, the destruction of infrastructure, and the lack of essential services.","topic":"Gaza","kind":"fact"},{"t":809,"quote":"Hayiti struggles with armed violence and extreme weather events causing a displacement crisis, a hunger crisis, and a health crisis.","topic":"Gaza","kind":"fact"},{"t":903,"quote":"I would like to thank Secretary General Gutz for his service and his dedication to reforming and rationalizing the UN system.","topic":"UN reform","kind":"fact"},{"t":915,"quote":"Every secretary general is shaped both by their era and by their own actions.","topic":"UN reform","kind":"fact"},{"t":958,"quote":"I've consistently called for a reformed security council. The world has changed and so should the UN.","topic":"UN reform","kind":"fact"},{"t":965,"quote":"There should be at least two new permanent seats for Africa, two for Asia-Pacific and one for Latin America.","topic":"UN reform","kind":"number"},{"t":983,"quote":"The world needs a functioning UN Security Council.","topic":"UN reform","kind":"fact"},{"t":1012,"quote":"Multilateral solutions uh are needed in an increasingly multipolar world.","topic":"UN reform","kind":"fact"},{"t":1051,"quote":"artificial intelligence is the most consequential technology in the history of mankind. It will impact science, the economy, politics, security, and the very essence of our humanity.","topic":"AI governance","kind":"fact"},{"t":1080,"quote":"Norway and Finland have together with leaders from nations around the world launched a call for companies, governments, regional organizations, and the UN to develop mechanisms to control frontier AI models.","topic":"AI governance","kind":"fact"},{"t":1142,"quote":"The foundations of the United States were built in San Francisco over 80 years ago.","topic":"UN reform","kind":"fact"}],"promises":[{"t":584,"quote":"Thus, I will offer you three remedies for a world in disorder.","topic":"Global economy","kind":"promise"},{"t":721,"quote":"For the collective benefit of the nations in this hall, we should continue to defend the rule of law and uphold its most fundamental principles.","topic":"International law","kind":"promise"},{"t":1101,"quote":"My country, Finland, wants the United Nations to succeed and will remain strongly engaged in its work.","topic":"AI governance","kind":"promise"},{"t":1108,"quote":"Therefore, we are standing for an election to the Security Council from 2029 to 2030.","topic":"AI governance","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Ceremony","text":"The assembly will hear an address by His Excellency Alexander Stub, President of the Republic of Finland. I request protocol to escort his excellency and invite him to address the assembly. Madame President, excellencies, ladies and gentlemen, let me just begin by paying tribute to uh the lady that is sitting right behind me, Ambassador Elena Kalo. She is the Finnish UN representative and she has had an absolutely wonderful 44year career uh in the Finnish diplomatic service and she will retire in the month of October. And I would like to thank her for her And of course with her president speaking here, you never know whether this will be the low point or the high point uh of her career."},{"t":65,"topic":"UN cooperation","text":"Be that as it may, um, former Secretary General Kofanan once said, and I quote, \"Whatever our differences, we stand or fall together.\" End of quote. When we forget this wisdom of Kofanan, disorder is what happens. Last year, from this very podium, I stated that foreign policy is based on three pillars: values, interests, and power. This year I come with something much simpler. A choice. A choice between or conflict. In today's world, cooperation is undermined by a lack of trust, disregard for rules, and the weakening of institutions. And we've heard that in so many speeches here today. Conflicts are spreading, bringing suffering, violence, violence, and injustice."},{"t":126,"topic":"armed conflicts","text":"According to some accounts, there are currently 65 active armed conflicts, more than at any time since the end of the Cold War. Now, competition will always be there. Nations compete now harder than they did a generation ago. This doesn't worry me. What does is that more and more of them now compete against the rules on which the international order rests. So this speech defends these rules and it calls for cooperation. It calls for multilateralism. Small nations need it to survive and large nations need it to be great. Upholding the most basic rules, values and institutions is our best option to ensure that competition does not escalate into conflict and that cooperation gains ground. Now I want to begin by analyzing how the world is changing today. And as a pragmatic Finn uh I will always try to deal with the world as it is because it often helps in building a world that I wish we would have."},{"t":199,"topic":"multilateralism","text":"In other words, a world which we can build together. I will then make a few suggestions about what we should do next. So here we go. I think we should all be steadfast defenders of As Strobe Talbbert reportedly remarked, multilateralism is hell and can be a real pain in the neck, but it is the best option for humanity as a whole. We need multilateralism in order to address our shared agenda, ranging from conflicts and climate change to sustainable development and artificial intelligence. Currently, however, we seem to be going the other way, more towards a non-ooperative and multipolar world order. This order, as it turns out, is based on zero sum deals, transactions, and unrestrained power. This is a short-sighted approach. Tempting as it may be for some, such a multipolar order will ultimately lead to conflict."},{"t":265,"topic":"Ukraine","text":"it will turn against us whether you represent a great power, a middle power or a small state like Finland. Between these two approaches, there's of course a third option, plurilateralism. It means building ad hoc coalitions when global cooperation is unattainable. And this is my first observation today. the emergence of flexible forms of cooperation around different themes and interests be it in the economy, climate, defense or technology. Coalition building can be a force of good but with one condition. It should not challenge multilateralism but build on it. It should support the UN system, not substitute it. The coalition of the willing for Ukraine is particularly close to my heart. It's a group of countries working to end Russia's war of aggression. The war is unlawful, unjustified, and unprovoked. Its solution will have far-reaching consequences for Ukraine and beyond."},{"t":327,"topic":"Ukraine","text":"It is really about upholding international rules. The coalition works for a just and lasting peace in Ukraine in accordance with the UN charter. It seeks to uphold the basic tenets of the international order. My second observation is that everywhere I travel around the world, I hear the word realignment. Realignment. Whether it is in Europe, Africa, the Middle East, Asia, or the Americans, nations are seeking new alliances and partnerships. This is a logical consequence in times of uncertainty and transformation. You seek security where you can get it. We're seeing an intensification of regional integration. akin to what we saw in the immediate aftermath of World War II. Regional organizations like the African Union, Gulf Cooperation Council, Merkosur, Asan or the EU build trust. When integration is not feasible, other forms of cooperation can prove essential."},{"t":392,"topic":"Helsinki Final Act","text":"We Finns are happy to point out the historic signing of the Helsinki Final Act in 1975. It brought together 35 nations in the midst of the Cold War and laid the foundations for what would later become the Organization for Security and Cooperation in Europe. Why do I give this example? Because at the time there was no trust. There were deep disagreements and outright hostility. Yet there was room for a process that reduced tensions and built common ground. I believe regions such as the Middle East, where conflicts are raging today, may consider something similar. Even in the face of conflict and grievance, a region may be able to agree on principles that foster cooperation and prevent further conflict. My third observation is that a new economic world order is taking shape. Instruments once used for economic integration such as trade, technology, energy, investment, and supply chains have become instruments of geopolitical competition."},{"t":463,"topic":"Global interdependence","text":"There was perhaps a time a naive at at times a naive belief that interdependence would bring about stability and peace. Now the focus on opportunities has been replaced by the focus on threats. We've entered a world of coercion where dependencies are Countries seek choke points that can be weaponized to pressure others. But dependencies are complex. No nation, not even the biggest ones, can go it alone. All coercive actions come at a cost. And even if a mightier state dominates in the one domain, a smaller state can respond in another. In the new geopolitical environment, the economic order of the post World War II era is seeking new forms. A new order must be based on a realistic understanding of power of the power balance in the world. We in the west must acknowledge that the global south and east are expanding are an expanding economic and political force."},{"t":531,"topic":"Global economy","text":"Many nations around the world have made remarkable advances in competence and knowhow. We should put this collective expertise to work for the global common good. Countries are right to be wary of dangerous dependencies, but our focus on the threats should not lead us to abandon We should strive for an economic world order built on institutions and agreements. Multilateralism is also needed in the global economy. Now, this was the first part. It's all good and well to diagnose the problem. In other words, too many nations now compete at the expense of basic rules. And that is why the world has slipped into disorder. But it matters more to find a prescription which would bring us back to order, stability, and cooperation. Thus, I will offer you three remedies for a world in disorder. To begin with, we need to go back to the basics of international law."},{"t":596,"topic":"International law","text":"On my recent visit to India, I came across a quote from Mahatma Gandhi and I quote, \"The breach of one rule inevitably leads to the breach of other rules.\" End of quote. These words resonate all too strongly today. So there is a kickon effect of breaking the rules. We've moved back to a world defined by raw power and self-interest. Rules and values seem to be taking a back seat. Some are ready to throw in the towel, prepared to accept the defeat of the international rules-based order. That is an exaggeration. International law has been questioned and challenged before. It has never been a perfect system. But we must admit that we are at a critical juncture. Fundamental norms are being questioned in a way that erodess confidence in the entire multilateral system. Therefore, the first remedy for a world in disorder is rule of law."},{"t":663,"topic":"International law","text":"Today, international norms are often presented as an obstacle to the pursuit of national interest. This is both wrong and dangerous. International law has never been merely an effort to achieve universal justice. But neither can it be reduced to a mere instrument of domination. It is not only about values nor about interest, but about both. Despite the rhetoric, no major power is likely to give up its ability to shape the rules. That's why we see major powers still engaged here in the United Nations. Even when actors claim to abandon the rules, they rather seek to replace existing rules with once more to their liking. Therefore, we will not face a world without rules. But we could be facing a world with less predictability, less restraint, a world based on rules that are more permissive for the powerful. For the collective benefit of the nations in this hall, we should continue to defend the rule of law and uphold its most fundamental principles."},{"t":731,"topic":"Sudan","text":"They include independence, sovereignty and territorial integrity of nations, freedom of navigation at sea, and accountability for the most serious international crimes. The second remedy is about humanitarian principles, many of which have been mentioned in the speeches here today. The world today has an unprecedented capacity to meet humanity's most pressing needs. Since the establishment of the United Nations, poverty has declined, access to basic education has expanded, literacy literacy has increased, and child mortality has fallen. Yet, we're witnessing tyranny, disregard for the vulnerable, and violence against civilians in many parts of the world. Poverty and distress are still widespread. For example, Sudan is devastated by war. Millions have been displaced and many face famine."},{"t":794,"topic":"Gaza","text":"For example, Gaza continues to be one of the world's most acute humanitarian emergencies marked by mass dis displacement, the destruction of infrastructure, and the lack of essential services. For example, Hayiti struggles with armed violence and extreme weather events causing a displacement crisis, a hunger crisis, and a health crisis. We must not grow indifferent to wars and human suffering, but instead channel our efforts into preventing conflicts, upholding human rights, and strengthening sustainable economies. Our growing material prosperity should not come at the expense of our ethical responsibilities. Now the third and final remedy is about language. In other words, how we treat each other. Unfortunately, there is no shortage of examples of those who use dismissive language to describe others to describe others and entire groups of people."},{"t":859,"topic":"UN reform","text":"Too often those with the most provocative rhetoric receive the greatest Provocation is rewarded with attention. Excess is misinterpreted as courage and exaggeration as truth. Language can foster cooperation, but can can also break the trust and turn competition into conflict. The recipe is simple but necessary. Avoid polarization. strengthen trust and listen to others. We need a dignified foreign policy and that starts here in the United Nations. Now ladies and gentlemen, let me conclude with the following remarks. I would like to thank Secretary General Gutz for his service and his dedication to reforming and rationalizing the UN system. This work must continue. Every secretary general is shaped both by their era and by their own actions."},{"t":921,"topic":"UN reform","text":"And I was reminded of this uh when I recently read the biographies of two former secretaries general Utant and Kofanan both highly influential leaders who navigated an era of great power tensions. Let me put forward a few suggestion for the new secretary general's consideration. whoever she may be and for the and for the international community at large. Now, since my first speech here two years ago, I've consistently called for a reformed security council. The world has changed and so should the UN. There should be at least two new permanent seats for Africa, two for Asia-Pacific and one for Latin America. No single state should have veto power. And if a member of the security council violates a UN charter, its voting rights should be suspended."},{"t":983,"topic":"UN reform","text":"The world needs a functioning UN Security Council. To move forward, we need to break the impass and be open for creative solutions. The need for reform also extends to the global economic architecture. It must be updated to reflect today's power balance. We have to make sure that international economic cooperation continues to be rules-based, legitimate, and representative. Multilateral solutions uh are needed in an increasingly multipolar world. We must also bring the United Nations back to peace mediation. The Secretary General as mediatorinchief will have a key role. The UN's legit legitimacy as a mediator is unique. Together, the UN and its member states can accomplish what neither can achieve alone. The UN needs to be at the center of rulemaking and institution building. regional integration and thematic coalitions can and should support it."},{"t":1049,"topic":"AI governance","text":"Now, let me finish by saying that artificial intelligence is the most consequential technology in the history of mankind. It will impact science, the economy, politics, security, and the very essence of our humanity. Humans can and should be in the driver's seat. We have a choice. We can compete, cooperate or slow down. For me, cooperation is the best way forward. This is why Norway and Finland have together with leaders from nations around the world launched a call for companies, governments, regional organizations, and the UN to develop mechanisms to control frontier AI models. And I would really like for as many UN member states as possible to join this initiative. My country, Finland, wants the United Nations to succeed and will remain strongly engaged in its work. Therefore, we are standing for an election to the Security Council from 2029 to 2030."},{"t":1116,"topic":"UN reform","text":"We're motivated by our belief in the UN charter and the values it stands for. We will prioritize peace, people, and partnerships. We are willing to take on the responsibility of the council membership at a time that calls for more peace. We want people and nations to thrive. We believe in dialogue and cooperation. Finally, let me make a procedural proposal. The foundations of the United States were built in San Francisco over 80 years ago. Today, we must restore balance to the world order. We must recommmit to the fundamental principles of the international order and we must embrace cooperation over conflict. What the world needs now is a new San Francisco moment. A moment where the world leaders come together to chart a way forward. A process to achieve this should start with a new secretary general. Thank you very much. On behalf of the assembly, I wish to thank the President of the Republic of"}],"compare":[{"topic":"International Law & Order","share":0.3672,"mean":0.0588,"rank":1,"others":102},{"topic":"UN & its reform","share":0.2865,"mean":0.2043,"rank":51,"others":170},{"topic":"Russia-Ukraine War","share":0.1144,"mean":0.0349,"rank":21,"others":44},{"topic":"Artificial Intelligence","share":0.0591,"mean":0.0504,"rank":69,"others":83},{"topic":"Israel–Palestine","share":0.0589,"mean":0.0524,"rank":63,"others":76},{"topic":"Global Economy","share":0.0581,"mean":0.0143,"rank":26,"others":31},{"topic":"Sudan","share":0.0559,"mean":0.007,"rank":11,"others":15}]};
